templates.template:
.button,
a.button {
	&.button--provider
	{
		&--th_cap_epicgames {
			.button-text::before {
				background-image: url('styles/themehouse/connected-account-providers/epic-games.png');
				background-size: contain;
				background-repeat: no-repeat;
				content: " ";

				height: 1em;
				width: 1em;
    			display: inline-block;
				text-align: center;
			}

			.m-buttonColorVariation(#333333, #ffffff);
		}

		&--th_cap_miniorange {
			.button-text::before {
				background-image: url('styles/themehouse/connected-account-providers/miniorange.png');
				background-size: contain;
				background-repeat: no-repeat;
				content: " ";

				height: 1em;
				width: 1em;
    			display: inline-block;
				text-align: center;
			}

			.m-buttonColorVariation(#ffffff, #f7934d);
		}

		&--linkedin {
			.m-buttonIcon(@fa-var-linkedin-in, .58em);
		}

		&--facebook {
			.m-buttonIcon(@fa-var-facebook-f, .58em);
		}

		&--th_cap_deviantart
		{
			.m-buttonColorVariation(#4dc47d, #06070d);
			background: linear-gradient(114deg,#4cddbd,#06f286);
			background-size: 120% 120%;
			background-position: -5px -5px;
			border-color: transparent;
			.m-buttonIcon(@fa-var-deviantart, .58em);
		}

		&--th_cap_dropbox {
			.m-buttonColorVariation(#0061ff, #fff);
			.m-buttonIcon(@fa-var-dropbox, .88em);
		}

		&--th_cap_discord {
			.m-buttonColorVariation(#7289DA, #FFFFFF);
			.m-buttonIcon(@fa-var-discord, .58em);
		}

		&--th_cap_amazon {
			.m-buttonColorVariation(#FF9900, #FFFFFF);
			.m-buttonIcon(@fa-var-amazon, .58em);
		}

		&--th_cap_reddit {
			.m-buttonColorVariation(#FF5700, #FFFFFF);
			.m-buttonIcon(@fa-var-reddit-alien, .88em);
		}

		&--th_cap_pinterest {
			.m-buttonColorVariation(#E60023, #FFFFFF);
			.m-buttonIcon(@fa-var-pinterest-p, .58em);
		}

		&--th_cap_instagram {
			.m-buttonColorVariation(#1400c8, #FFFFFF);
			background: linear-gradient(-135deg,#1400c8,#b900b4,#f50000);
			background-size: 120% 120%;
			background-position: -5px -5px;
			border-color: transparent;
			.m-buttonIcon(@fa-var-instagram, .58em);
		}

		&--th_cap_twitch {
			.m-buttonColorVariation(#6441A4, #FFFFFF);
			.m-buttonIcon(@fa-var-twitch, .88em);
		}

		&--th_cap_vk {
			.m-buttonColorVariation(#4680C2, #FFFFFF);
			.m-buttonIcon(@fa-var-vk, .88em);
		}

		&--th_cap_paypal {
			.m-buttonColorVariation(#003087, #FFFFFF);
			background: linear-gradient(-120deg, #003087, #009cde, #012169);
			background-size: 120% 120%;
			background-position: -5px -5px;
			border-color: transparent;
			.m-buttonIcon(@fa-var-paypal, .58em);
		}

		&--th_cap_vimeo {
			.m-buttonColorVariation(#1ab7ea, #FFFFFF);
			.m-buttonIcon(@fa-var-vimeo-v, .58em);
		}

		&--th_cap_spotify {
			.m-buttonColorVariation(#1DB954, #191414);
			.m-buttonIcon(@fa-var-spotify, .58em);
		}

		&--th_cap_steam {
			.m-buttonColorVariation(#171A21, #c7d5e0);
			.m-buttonIcon(@fa-var-steam-symbol, .58em);
		}

		&--th_cap_imgur {
			.m-buttonColorVariation(#85bf25, #000000);
			.m-buttonIcon(@fa-var-sign-in-alt, .58em);

			> .button-text:before,
			.button-icon
			{
				.m-faBase();
			}
		}

		&--th_cap_battlenet {
			.m-buttonColorVariation(#182336, #01c6ea);
			.m-buttonIcon(@fa-var-battle-net, .88em);
		}

		&--th_cap_gitlab {
			.m-buttonColorVariation(#e65328, #ffffff);
			.m-buttonIcon(@fa-var-gitlab, .58em);
		}

		&--th_cap_woocommerce {
			.m-buttonColorVariation(#444140, #00749C);
			.m-buttonIcon(@fa-var-wordpress-simple, .58em);
		}

		&--th_cap_stackexchange {
			.m-buttonColorVariation(#1e5397, #91d8f4);
			.m-buttonIcon(@fa-var-stack-exchange, .58em);
		}

		&--th_cap_xing {
			.m-buttonColorVariation(#026466, #cfdc00);
			.m-buttonIcon(@fa-var-xing, .58em);
		}

		&--th_cap_line {
			.m-buttonColorVariation(#00c300, #ffffff);
			.m-buttonIcon(@fa-var-line, .58em);
		}

		&--th_cap_imis {
			.m-buttonColorVariation(#01a7e1, #ffffff);
			.m-buttonIcon(@fa-var-sign-in-alt, .58em);

			> .button-text:before,
			.button-icon
			{
				.m-faBase();
			}
		}

		&--th_cap_keycloak {
			.m-buttonColorVariation(#e0e0e0, #008aaa);
			.m-buttonIcon(@fa-var-sign-in-alt, .58em);

			> .button-text:before,
			.button-icon
			{
				.m-faBase();
			}
		}

		&--th_cap_apple {
			.m-buttonColorVariation(#000, #fff);
			.m-buttonIcon(@fa-var-apple, .58em);
		}
	}
}
